import numpy as np


def r(x):
    # Non-linear monotonic transformation mapping [0, 1] to [0.2, 1.0]
    # where r(x) >= x for all x in [0, 1]
    return float(x + 0.2 * (1.0 - x**2))


def R(y_orig, y_new) -> bool:
    # Ensure both outputs are valid finite floats
    return np.isfinite(y_orig) and np.isfinite(y_new)
